<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++20 (64) code you have to rewrite:
<original_code>
#include <bits/stdc++.h>
using namespace std;
#define SET(a) memset(a, -1, sizeof a) 
#define R(i, a, b) for (int i = (a); i < (b); ++i)
#define L(i, a, b) for (int i = (b) - 1; i >= (a); --i)
using i64 = long long;

constexpr int M = 1000000007;

struct mint {
  int x;

  mint(int _x = 0) : x(_x) {}
  const int &operator () () const { return x; }
};

mint operator + (const mint &a, const mint &b) { const int x = a.x + b.x; return x < M ? x : x - M; }
mint operator - (const mint &a, const mint &b) { const int x = a.x - b.x; return x < 0 ? x + M : x; }
mint operator * (const mint &a, const mint &b) { return i64(a.x) * b.x % M; }

mint pw(mint a, int x = M - 2) {
  mint res = 1;
  for (; x; x >>= 1, a = a * a) if (x & 1) res = res * a;
  return res;
}

constexpr int mod = 998244353, base = 1000000, m = 6;
i64 N, pos; int cnt_suf;
mint sum[m + 1], res = 0;
vector<int> suf[m + 1];

void dfs0(int i, i64 n) {
  int x = ((pos++ - n) % mod + mod) % mod;
  sum[i] = sum[i] + x; suf[i].push_back(x);
  if (i == m) return;
  R(c, 0, 10) dfs0(i + 1, n * 10 + c);
}

void dfs1(i64 n) {
  if (n >= N) return;
  if ((n + 1) * base <= N and n * base * 10 >= N) {
    i64 p = 1;
    R(i, 0, m + 1) {
      mint ns = suf[i].size();
      int x = ((pos - p * n) % mod + mod) % mod;
      int cnt = lower_bound(suf[i].begin(), suf[i].end(), mod - x) - suf[i].begin();
      res = res + ns * x + sum[i] - (ns - cnt) * mod;
      p *= 10;
    }
    pos += cnt_suf;
    return;
  }
  res = res + ((pos++ - n) % mod + mod) % mod;
  R(c, 0, 10) dfs1(n * 10 + c);
}

int main() {
  ios::sync_with_stdio(false); cin.tie(0);
  cin >> N; N += 1; dfs0(0, 0);
  R(i, 0, m + 1) { cnt_suf += suf[i].size(); sort(suf[i].begin(), suf[i].end()); }
  pos = 1; R(c, 1, 10) dfs1(c);
  cout << res() << '\n';
  return 0;
}
